import ledger


def _encode_amount(cents):
    """Encode an integer minor-unit amount as '<sign><digits>#<check>'."""
    sign = '-' if cents < 0 else '+'
    digits = str(abs(int(cents)))
    check = sum(int(d) for d in digits) % 10
    return "{}{}#{}".format(sign, digits, check)


def transfer(acct, cents, reason):
    """Post `cents` (minor units) to `acct` with `reason` as memo; return entry id."""
    return ledger.post(acct, _encode_amount(cents), reason)

